def is_valid_iso_datetime(s):
    if s.count('T') != 1:
        return False
    date_part, time_part = s.split('T')
    dparts = date_part.split('-')
    if len(dparts) != 3:
        return False
    y, m, d = dparts
    if not (len(y) == 4 and y.isdigit() and len(m) == 2 and m.isdigit() and len(d) == 2 and d.isdigit()):
        return False
    year, month, day = int(y), int(m), int(d)
    if not (1 <= year <= 9999 and 1 <= month <= 12):
        return False
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    dim = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if not (1 <= day <= dim[month - 1]):
        return False
    tparts = time_part.split(':')
    if len(tparts) != 3:
        return False
    h, mi, sec = tparts
    if not (len(h) == 2 and h.isdigit() and len(mi) == 2 and mi.isdigit() and len(sec) == 2 and sec.isdigit()):
        return False
    return 0 <= int(h) <= 23 and 0 <= int(mi) <= 59 and 0 <= int(sec) <= 59

def is_valid_date_range(start, end):
    def parse(s):
        parts = s.split('-')
        if len(parts) != 3:
            return None
        y, m, d = parts
        if not (len(y) == 4 and y.isdigit() and len(m) == 2 and m.isdigit() and len(d) == 2 and d.isdigit()):
            return None
        year, month, day = int(y), int(m), int(d)
        if not (1 <= year <= 9999 and 1 <= month <= 12):
            return None
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        dim = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if not (1 <= day <= dim[month - 1]):
            return None
        return (year, month, day)
    s1 = parse(start)
    s2 = parse(end)
    if s1 is None or s2 is None:
        return False
    return s1 <= s2

def is_valid_us_date(s):
    parts = s.split('/')
    if len(parts) != 3:
        return False
    m, d, y = parts
    if not (len(m) == 2 and m.isdigit() and len(d) == 2 and d.isdigit() and len(y) == 4 and y.isdigit()):
        return False
    month, day, year = int(m), int(d), int(y)
    if not (1 <= month <= 12 and 1 <= year <= 9999):
        return False
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    dim = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return 1 <= day <= dim[month - 1]

def is_valid_military_time(s):
    if len(s) != 4 or not s.isdigit():
        return False
    h, m = int(s[:2]), int(s[2:])
    return 0 <= h <= 23 and 0 <= m <= 59

def is_valid_year_month(s):
    parts = s.split('-')
    if len(parts) != 2:
        return False
    y, m = parts
    if not (len(y) == 4 and y.isdigit() and len(m) == 2 and m.isdigit()):
        return False
    return 1 <= int(m) <= 12

def is_palindrome_identifier(s):
    if not s or not s.isalnum():
        return False
    lowered = s.lower()
    return lowered == lowered[::-1]

def is_numeric_palindrome(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def is_valid_palindrome_phrase(s):
    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]

def is_binary_palindrome(s):
    if not s or any(c not in '01' for c in s):
        return False
    return s == s[::-1]

def is_near_palindrome(s):
    def is_pal(sub):
        return sub == sub[::-1]
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return is_pal(s[i + 1:j + 1]) or is_pal(s[i:j])
        i += 1
        j -= 1
    return True

def is_valid_masked_card_number(s):
    groups = s.split('-')
    if len(groups) != 4:
        return False
    for g in groups[:3]:
        if g != 'XXXX':
            return False
    last = groups[3]
    return len(last) == 4 and last.isdigit()

def is_valid_asterisk_masked_card(s):
    if len(s) != 16:
        return False
    return s[:12] == '*' * 12 and s[12:].isdigit()

def is_valid_card_display_format(s):
    groups = s.split(' ')
    if len(groups) != 4:
        return False
    for g in groups:
        if g == 'XXXX':
            continue
        if len(g) == 4 and g.isdigit():
            continue
        return False
    return True

def is_valid_last4_mask_match(full_number, masked):
    if len(full_number) != 16 or not full_number.isdigit():
        return False
    if len(masked) != 16:
        return False
    if masked[:12] != '*' * 12:
        return False
    return masked[12:] == full_number[12:]

def is_valid_account_mask(s):
    if len(s) < 8 or not s.startswith('****'):
        return False
    if s[4] == '*':
        return False
    digits = s[4:]
    return digits.isdigit() and 4 <= len(digits) <= 12

def is_valid_python_identifier(s):
    keywords = {'if', 'else', 'elif', 'for', 'while', 'def', 'return', 'class', 'import', 'in',
                'not', 'and', 'or', 'True', 'False', 'None', 'break', 'continue', 'pass', 'try',
                'except', 'finally', 'with', 'as', 'lambda', 'yield'}
    if not s:
        return False
    if not (s[0].isalpha() or s[0] == '_'):
        return False
    if not all(c.isalnum() or c == '_' for c in s):
        return False
    return s not in keywords

def is_valid_semver(s):
    parts = s.split('.')
    if len(parts) != 3:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
    return True
